alter table public.articles add constraint articles_featured_image_type_check CHECK ((featured_image_type = ANY (ARRAY['url'::text, 's3'::text])));
alter table public.catalog_descriptions add constraint catalog_descriptions_locale_check CHECK ((locale = ANY (ARRAY['cs'::text, 'en'::text, 'uk'::text])));
alter table public.catalog_descriptions add constraint catalog_descriptions_scope_type_check CHECK ((scope_type = ANY (ARRAY['model'::text, 'series'::text, 'brand'::text])));
alter table public.discounts add constraint discounts_discount_type_check CHECK (((discount_type)::text = ANY ((ARRAY['percentage'::character varying, 'fixed'::character varying])::text[])));
alter table public.discounts add constraint discounts_discount_value_check CHECK ((discount_value > (0)::numeric));
alter table public.discounts add constraint discounts_scope_type_check CHECK (((scope_type)::text = ANY ((ARRAY['brand'::character varying, 'series'::character varying, 'model'::character varying, 'all_models'::character varying])::text[])));
alter table public.discounts add constraint valid_dates CHECK (((expires_at IS NULL) OR (expires_at > starts_at)));
alter table public.discounts add constraint valid_scope CHECK (((((scope_type)::text = 'brand'::text) AND (brand_id IS NOT NULL)) OR (((scope_type)::text = 'series'::text) AND (series_id IS NOT NULL)) OR (((scope_type)::text = 'model'::text) AND (model_id IS NOT NULL)) OR ((scope_type)::text = 'all_models'::text)));
alter table public.discounts add constraint valid_service_ids CHECK ((array_length(service_ids, 1) > 0));
alter table public.page_views add constraint page_views_date_check CHECK ((created_at <= CURRENT_TIMESTAMP));
alter table public.remonline_order_sync_issues add constraint remonline_order_sync_issues_attempts_check CHECK ((attempts >= 1));
alter table public.remonline_order_sync_issues add constraint remonline_order_sync_issues_status_check CHECK ((status = ANY (ARRAY['open'::text, 'resolved'::text, 'ignored'::text])));
alter table public.service_scope_faq_translations add constraint service_scope_faq_translations_locale_check CHECK ((locale = ANY (ARRAY['cs'::text, 'en'::text, 'uk'::text])));
alter table public.service_scope_faqs add constraint service_scope_faqs_scope_type_check CHECK ((scope_type = ANY (ARRAY['model'::text, 'series'::text])));
alter table public.service_scope_translations add constraint service_scope_translations_locale_check CHECK ((locale = ANY (ARRAY['cs'::text, 'en'::text, 'uk'::text])));
alter table public.service_scope_translations add constraint service_scope_translations_scope_type_check CHECK ((scope_type = ANY (ARRAY['model'::text, 'series'::text, 'brand'::text])));
alter table public.services add constraint check_duration_positive CHECK ((duration_hours > (0)::numeric));
alter table public.services add constraint check_warranty_positive CHECK ((warranty_months > 0));
alter table public.user_invoices add constraint user_invoices_sync_source_check CHECK ((sync_source = ANY (ARRAY['webhook'::text, 'manual'::text])));
alter table public.user_invoices add constraint user_invoices_sync_status_check CHECK ((sync_status = ANY (ARRAY['synced'::text, 'error'::text])));
alter table public.users add constraint users_locale_check CHECK ((locale = ANY (ARRAY['uk'::text, 'en'::text, 'cs'::text])));
alter table public.users add constraint users_remonline_contact_type_check CHECK ((remonline_contact_type = ANY (ARRAY['person'::text, 'organization'::text])));
alter table public.users add constraint users_remonline_sync_attempts_check CHECK ((remonline_sync_attempts >= 0));
alter table public.users add constraint users_remonline_sync_status_check CHECK ((remonline_sync_status = ANY (ARRAY['pending'::text, 'synced'::text, 'error'::text])));
alter table public.webhook_logs add constraint webhook_logs_status_check CHECK ((status = ANY (ARRAY['received'::text, 'success'::text, 'failed'::text, 'error'::text])));

